def node_state(node):
    ordinary(node)
    path=provider_path(node)/'provider/owner.json'
    raw_owner=load(path) if path.exists() else None
    owner={k:raw_owner.get(k) for k in ('state','cacheId','pool','finalizeAcknowledged','deleteAcknowledged')} if raw_owner else None
    journal=load(DEPLOYMENT/'cohort-state.json')
    units={}
    for unit in ('jwk-aenv-lazy-four-32ce41c-'+node+'.service','jwk-ub-lazy-four-'+node+'-v2.service'):
        p=subprocess.run(['/usr/bin/systemctl','show',unit,'--property=LoadState,ActiveState,MainPID'],capture_output=True,text=True,timeout=15)
        value=dict(x.split('=',1) for x in p.stdout.splitlines() if '=' in x)
        need(p.returncode==0 or value.get('LoadState')=='not-found','Cannot establish own unit state')
        units[unit]=value
    ready=False
    if (WORK/'root-scope.json').exists():
        path=root_ready_path()
