COORDINATOR_LOCK=None


def lock_coordinator():
    import fcntl
    global COORDINATOR_LOCK
    need(COORDINATOR_LOCK is None,'Coordinator lock already held')
    path=WORK/'coordinator.lock'
    fd=os.open(path,os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW|os.O_CLOEXEC,0o600)
    try:
        meta=os.fstat(fd)
        need(stat.S_ISREG(meta.st_mode) and meta.st_uid==1204 and meta.st_nlink==1,'Unexpected coordinator mutex')
        fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
        COORDINATOR_LOCK=fd  # Held until this one-shot process exits.
    except BaseException:
        os.close(fd);raise


def tracked_root(state,node,operation):
    # Persist intent BEFORE calling root. A lost reply is not silently repeated.
    key='runtimeIntents' if operation in ('runtime-off','runtime-lazy') else 'providerIntents'
    if operation in ('runtime-off','runtime-lazy','provider-start'):
        if node not in state[key]:state[key].append(node)
        if operation.startswith('runtime-') and node in state['runtimeStopped']:state['runtimeStopped'].remove(node)
    save(WORK/'execution-state.json',state)
    value=root_command(node,operation)
    state['events'].append({'node':node,'operation':operation,'status':'confirmed','sequence':value['sequence']})
    if operation=='runtime-stop' and node not in state['runtimeStopped']:state['runtimeStopped'].append(node)
    save(WORK/'execution-state.json',state)
    return value


def settle(state):
    failures=[]
    def action(label,fn):
        try:
            value=fn();state['events'].append({'cleanup':label,'status':'confirmed'})
            save(WORK/'execution-state.json',state);return value
        except Exception as error:
            failures.append({'step':label,'errorType':type(error).__name__,
                             'reason':str(error)[:400] if isinstance(error,RuntimeError) else 'Inspect retained logs'})
            return None
    # A supervisor may have become ready while the coordinator was waiting on
    # the other node. Discover both before claiming that all supervision ended.
    for node in ('node-a','node-b'):
        current=action('inspect-'+node,lambda node=node:state_for(node))
        if current and current.get('rootReady') and node not in state['rootReady']:
            state['rootReady'].append(node);save(WORK/'execution-state.json',state)
    if failures:return {'status':'CLEANUP_PRESERVED_UNCERTAIN_NODE_STATE','failures':failures}
    for node in ('node-b','node-a'):
        if node in state['runtimeIntents'] and node not in state['runtimeStopped']:
            action('stop-'+node,lambda node=node:tracked_root(state,node,'runtime-stop'))
    if failures:
        return {'status':'CLEANUP_PRESERVED_UNCERTAIN_RUNTIME','failures':failures}
    for node in ('node-b','node-a'):
        if node not in state['providerIntents'] or node in state['providersReleased']:continue
        def retire(node=node):
            current=state_for(node);owner=current['provider']
            need(owner is not None,'Provider startup outcome lacks a receipt; preserve owner/import state')
            if owner.get('state')!='released':
                need(owner.get('state')=='serving','Provider is unresolved; no repeated SDK operation')
                if node=='node-a':
                    r=subprocess.run([PYTHON,'-I','-B',str(HELPERS/'lazy_four_provider.py'),'retire','--node',node,'--run'],capture_output=True,timeout=180)
                else:r=subprocess.run(remote_command(['b-retire']),capture_output=True,timeout=200)
                need(r.returncode==0,'Provider retirement refused/uncertain; preserve metadata connection')
            after=state_for(node)['provider']
            need(after.get('state')=='released' and after.get('finalizeAcknowledged') is True
                 and (node=='node-b' or after.get('deleteAcknowledged') is True),'Provider release not acknowledged')
            state['providersReleased'].append(node)
        action('release-'+node,retire)
        if failures:return {'status':'CLEANUP_PRESERVED_UNCERTAIN_PROVIDER','failures':failures}
    for node in ('node-b','node-a'):
        if node not in state['rootReady'] or node in state['rootsFinished']:continue
        def finish(node=node):
            deadline=time.monotonic()+40
            while True:
                current=state_for(node)
                if all(x.get('MainPID')=='0' and x.get('ActiveState')=='inactive' for x in current['units'].values()):break
                need(time.monotonic()<deadline,'Own service exit is not yet confirmed');time.sleep(.5)
            root_finish_check(current)
            tracked_root(state,node,'finish');state['rootsFinished'].append(node)
        action('finish-'+node,finish)
    if failures:return {'status':'CLEANUP_PRESERVED_ROOT_STATE','failures':failures}
    if state['metadataStarted'] and not state['metadataStopped']:
        def close_metadata():
            stop_metadata({'PUBLIC_PINS':PUBLIC_PINS,'SSH':SSH})
            need(not state_for('node-b')['metadataSocketPresent'],'B metadata endpoint remains')
            state['metadataStopped']=True
        action('metadata-stop',close_metadata)
    return {'status':'V2_OWNED_RESOURCES_RELEASED' if not failures else 'CLEANUP_PRESERVED_TRANSPORT_STATE',
            'failures':failures}


